// Some portions generated by Claude
/**
 * Arrow geometry: for every arrow the first clean choice of
 *
 * 1. the canvas's own straight line between ports aimed at the other card's centre;
 * 2. a straight line between other points of the two cards' borders, preferring the sides that face each other (an
 *    arrow to a card in a column beside a hub ends on the card's inner side instead of cutting the card below);
 * 3. the shortest path around the cards in the way, through a visibility graph of their padded corners (Dobkin et
 *    al.'s spline router and Dwyer and Nachmanson's tangent-visibility routing take the same first step), drawn with
 *    rounded corners and kept only when it is not much longer than the straight line.
 *
 * Parallel arrows between the same two cards keep their lanes (curves on alternate sides). Choices 2 and 3 are routes
 * (`EdgeRoute`), which the canvas honours while both cards keep the centres they were computed for.
 */
import {computeEdgeLanes, computeEdgePorts, edgeBendForLane, edgePortKey, graphNodeSize, nodeBoundaryPoint, nodeCornerRadius} from './graph-geometry.ts';
import {segmentHitsBox} from './graph-layout-stress.ts';
import {SpatialGrid} from './spatial-grid.ts';
import type {EdgeRoute, GraphEdge, GraphNode, PointerPosition} from './graph-types.ts';

/** Space kept between an arrow and a card it passes. */
const CLEARANCE = 4;
/** Padding of card corners for detours. */
const DETOUR_PADDING = 14;
/** Arrows with more cards than this skip detours (a straight line or a moved port still applies). */
const DETOUR_EDGE_LIMIT = 1600;
/** Detours are searched among at most this many cards near the arrow. */
const DETOUR_OBSTACLE_LIMIT = 80;

/** Extra cost of a detour leg for every card it passes within `ROOM` of. */
function crowding(a: PointerPosition, b: PointerPosition, near: readonly Box[]) {
  let cost = 0;
  for (const box of near) {
    const gap = boxDistance(a, b, box);
    if (gap < ROOM) cost += (ROOM - gap) * 2;
  }
  return cost;
}

/** Room a detour likes to keep from the cards it passes. */
const ROOM = 28;

/** Distance from segment a–b to the nearest point of a card's box. */
function boxDistance(a: PointerPosition, b: PointerPosition, box: Box) {
  const minX = box.x - box.halfWidth, maxX = box.x + box.halfWidth, minY = box.y - box.halfHeight, maxY = box.y + box.halfHeight;
  if (segmentHitsBox(a.x, a.y, b.x, b.y, minX, minY, maxX, maxY)) return 0;
  const clampX = (v: number) => Math.max(minX, Math.min(maxX, v)), clampY = (v: number) => Math.max(minY, Math.min(maxY, v));
  let best = Infinity;
  for (let i = 0; i <= 8; i++) {
    const t = i / 8, x = a.x + (b.x - a.x) * t, y = a.y + (b.y - a.y) * t;
    best = Math.min(best, Math.hypot(x - clampX(x), y - clampY(y)));
  }
  return best;
}

type Box = {id: string; x: number; y: number; halfWidth: number; halfHeight: number};
type Obstacles = {boxes: Box[]; grid: SpatialGrid};

function obstaclesOf(nodes: readonly GraphNode[]): Obstacles {
  const grid = new SpatialGrid(192), boxes: Box[] = [];
  for (const node of nodes) {
    const {width, height} = graphNodeSize(node);
    const box = {id: node.id, x: node.x ?? 0, y: node.y ?? 0, halfWidth: width / 2, halfHeight: height / 2};
    boxes.push(box);
    grid.insert({minX: box.x - box.halfWidth, maxX: box.x + box.halfWidth, minY: box.y - box.halfHeight, maxY: box.y + box.halfHeight});
  }
  return {boxes, grid};
}

/** Cards (other than `except`) the segment a–b passes within `clearance` of. */
function blockers(o: Obstacles, a: PointerPosition, b: PointerPosition, except: ReadonlySet<string>, clearance: number, found: number[] = []) {
  o.grid.search(Math.min(a.x, b.x) - clearance, Math.min(a.y, b.y) - clearance, Math.max(a.x, b.x) + clearance, Math.max(a.y, b.y) + clearance, found);
  const hits: number[] = [];
  for (const i of found) {
    const box = o.boxes[i];
    if (except.has(box.id)) continue;
    if (segmentHitsBox(a.x, a.y, b.x, b.y, box.x - box.halfWidth - clearance, box.y - box.halfHeight - clearance,
      box.x + box.halfWidth + clearance, box.y + box.halfHeight + clearance)) hits.push(i);
  }
  return hits;
}

/** Points on a card's border to try as an arrow's end: along each side, away from the rounded corners. */
function borderPoints(node: GraphNode): PointerPosition[] {
  const {width, height} = graphNodeSize(node), x = node.x ?? 0, y = node.y ?? 0, r = nodeCornerRadius(node) + 2, pad = 1.5;
  const points: PointerPosition[] = [];
  for (const f of [0.5, 0.3, 0.7, 0.12, 0.88]) {
    const along = -width / 2 + r + (width - 2 * r) * f, down = -height / 2 + r + (height - 2 * r) * f;
    points.push({x: x + along, y: y - height / 2 - pad}, {x: x + along, y: y + height / 2 + pad});
    points.push({x: x - width / 2 - pad, y: y + down}, {x: x + width / 2 + pad, y: y + down});
  }
  return points;
}

/** Whether the segment leaves `node` at `from` without running back across the card. */
function leavesCard(node: GraphNode, from: PointerPosition, to: PointerPosition) {
  const {width, height} = graphNodeSize(node), x = node.x ?? 0, y = node.y ?? 0;
  // Sample just after the start: it must already be outside the card.
  const t = Math.min(0.5, 3 / Math.max(1, Math.hypot(to.x - from.x, to.y - from.y)));
  const px = from.x + (to.x - from.x) * t, py = from.y + (to.y - from.y) * t;
  return !(Math.abs(px - x) < width / 2 && Math.abs(py - y) < height / 2);
}

/** A straight line between two other border points of the cards, clear of every other card; the closest to the centre line. */
function movedPorts(source: GraphNode, target: GraphNode, o: Obstacles, except: ReadonlySet<string>) {
  const sc = {x: source.x ?? 0, y: source.y ?? 0}, tc = {x: target.x ?? 0, y: target.y ?? 0};
  const direct = Math.atan2(tc.y - sc.y, tc.x - sc.x);
  const centreDistance = Math.hypot(tc.x - sc.x, tc.y - sc.y);
  let best: {from: PointerPosition; to: PointerPosition; cost: number} | null = null;
  const consider = (from: PointerPosition, to: PointerPosition) => {
    if (!leavesCard(source, from, to) || !leavesCard(target, to, from)) return;
    const length = Math.hypot(to.x - from.x, to.y - from.y);
    const angle = Math.abs(Math.atan2(Math.sin(Math.atan2(to.y - from.y, to.x - from.x) - direct), Math.cos(Math.atan2(to.y - from.y, to.x - from.x) - direct)));
    const cost = length + centreDistance * 0.6 * angle;
    if (best && cost >= best.cost) return;
    if (blockers(o, from, to, except, CLEARANCE).length) return;
    best = {from, to, cost};
  };
  const targetPoints = borderPoints(target), sourcePoints = borderPoints(source);
  // The hub's end aims at the other end (its arrows fan from its centre); the other end moves along its sides.
  for (const to of targetPoints) consider(nodeBoundaryPoint(source, to), to);
  for (const from of sourcePoints) consider(from, nodeBoundaryPoint(target, from));
  if (!best) for (const from of sourcePoints) for (const to of targetPoints) consider(from, to);
  return best as {from: PointerPosition; to: PointerPosition; cost: number} | null;
}

/** Shortest path around the cards in the way, through their padded corners; null when none is short enough. */
function detour(source: GraphNode, target: GraphNode, o: Obstacles, except: ReadonlySet<string>) {
  const sc = {x: source.x ?? 0, y: source.y ?? 0}, tc = {x: target.x ?? 0, y: target.y ?? 0};
  const straight = Math.hypot(tc.x - sc.x, tc.y - sc.y);
  // Cards in a corridor around the straight line: a detour that is not much longer than the line stays inside it.
  const corridor = 160 + straight * 0.2;
  const found: number[] = [];
  o.grid.search(Math.min(sc.x, tc.x) - corridor, Math.min(sc.y, tc.y) - corridor, Math.max(sc.x, tc.x) + corridor, Math.max(sc.y, tc.y) + corridor, found);
  const near = found.map(i => o.boxes[i]).filter(box => !except.has(box.id) &&
    boxDistance(sc, tc, box) <= corridor);
  if (near.length > DETOUR_OBSTACLE_LIMIT) return null;
  const pad = DETOUR_PADDING;
  const points: PointerPosition[] = [sc, tc];
  for (const box of near) {
    const hw = box.halfWidth + pad, hh = box.halfHeight + pad;
    points.push({x: box.x - hw, y: box.y - hh}, {x: box.x + hw, y: box.y - hh}, {x: box.x + hw, y: box.y + hh}, {x: box.x - hw, y: box.y + hh});
  }
  // Corners inside another padded card are useless.
  const usable = points.map((p, i) => i < 2 || !near.some(box => Math.abs(p.x - box.x) < box.halfWidth + pad - 0.5 && Math.abs(p.y - box.y) < box.halfHeight + pad - 0.5));
  const visible = (a: PointerPosition, b: PointerPosition) => !near.some(box => segmentHitsBox(a.x, a.y, b.x, b.y,
    box.x - box.halfWidth - CLEARANCE, box.y - box.halfHeight - CLEARANCE, box.x + box.halfWidth + CLEARANCE, box.y + box.halfHeight + CLEARANCE));
  // A* from the source centre to the target centre; the end cards are not obstacles.
  const count = points.length, distance = new Float64Array(count).fill(Infinity), previous = new Int32Array(count).fill(-1);
  const closed = new Uint8Array(count);
  distance[0] = 0;
  const heuristic = (i: number) => Math.hypot(points[i].x - tc.x, points[i].y - tc.y);
  for (let step = 0; step < count; step++) {
    let current = -1, value = Infinity;
    for (let i = 0; i < count; i++) if (!closed[i] && usable[i] && distance[i] + heuristic(i) < value) { value = distance[i] + heuristic(i); current = i; }
    if (current < 0 || current === 1) break;
    closed[current] = 1;
    for (let next = 0; next < count; next++) {
      if (closed[next] || !usable[next] || next === current) continue;
      const length = Math.hypot(points[next].x - points[current].x, points[next].y - points[current].y);
      // Each corner costs a little, so a straight run beats a zigzag of the same length.
      const candidate = distance[current] + length + (next === 1 ? 0 : 6);
      if (candidate >= distance[next]) continue;
      if (!visible(points[current], points[next])) continue;
      // Passing close by a card costs extra, so of two equally short ways round the roomier one wins.
      const tight = candidate + crowding(points[current], points[next], near);
      if (tight >= distance[next]) continue;
      distance[next] = tight; previous[next] = current;
    }
  }
  if (!Number.isFinite(distance[1]) || distance[1] > straight * 1.45 + 120) return null;
  const path: PointerPosition[] = [];
  for (let at = 1; at >= 0; at = previous[at]) path.unshift(points[at]);
  if (path.length < 3) return null;
  // Replace the centres by the border points where the path leaves and enters the cards.
  path[0] = nodeBoundaryPoint(source, path[1]);
  path[path.length - 1] = nodeBoundaryPoint(target, path[path.length - 2]);
  return path;
}

/**
 * Bends (parallel lanes) and routes for the drawn arrows of placed cards. Arrows the canvas already draws cleanly get
 * neither.
 */
export function routeEdges(nodes: readonly GraphNode[], edges: readonly GraphEdge[]) {
  const bends = new Map<string, number>(), routes = new Map<string, EdgeRoute>();
  const byId = new Map(nodes.map(node => [node.id, node]));
  const lanes = computeEdgeLanes(edges as GraphEdge[]);
  const ports = computeEdgePorts(nodes as GraphNode[], edges as GraphEdge[]);
  const o = obstaclesOf(nodes);
  const detours = edges.length <= DETOUR_EDGE_LIMIT;
  for (const edge of edges) {
    const source = byId.get(edge.source), target = byId.get(edge.target);
    if (!source || !target) continue;
    const sc = {x: source.x ?? 0, y: source.y ?? 0}, tc = {x: target.x ?? 0, y: target.y ?? 0};
    const lane = lanes.get(edge.id) ?? 0;
    if (lane !== 0 || source.id === target.id) {
      bends.set(edge.id, edgeBendForLane(lane, Math.hypot(tc.x - sc.x, tc.y - sc.y)));
      continue;
    }
    bends.set(edge.id, 0);
    const except = new Set([source.id, target.id]);
    const from = ports.get(edgePortKey(edge.id, source.id)) ?? nodeBoundaryPoint(source, tc);
    const to = ports.get(edgePortKey(edge.id, target.id)) ?? nodeBoundaryPoint(target, sc);
    if (!blockers(o, from, to, except, CLEARANCE).length) continue;
    const moved = movedPorts(source, target, o, except);
    if (moved) { routes.set(edge.id, {source: sc, target: tc, points: [moved.from, moved.to]}); continue; }
    if (!detours) continue;
    const path = detour(source, target, o, except);
    if (path) routes.set(edge.id, {source: sc, target: tc, points: path});
  }
  return {bends, routes};
}
